/**
 * Regions, biomes and exclusive materials.
 *
 * Every landmass on the chart is one region, matched to the nearest centre below;
 * the unnamed skerries take the region of the island they sit nearest. A region
 * decides three things: which biomes may appear on it, which rock and ores it
 * yields, and which tree species grow there. Materials listed on one region and
 * no other are exclusive to it by construction.
 *
 * Generated by Archipelago Forge.
 */
import { hash2 } from './noise';
import type { Atlas } from './atlas-world';

export const RockType = { Granite: 0, Slate: 1, Marble: 2, Sandstone: 3 } as const;
export type RockType = (typeof RockType)[keyof typeof RockType];

export const Ore = {
  None: 0, Iron: 1, Copper: 2, Tin: 3, Lead: 4, Zinc: 5, Adamantite: 6, Glimmersteel: 7, Seryll: 8,
} as const;
export type Ore = (typeof Ore)[keyof typeof Ore];

/** Tree species index. Cherry is new - add an entry to TREE_DEFS in tiles.ts: */
/*   { name: 'Cherry', shape: 'round', trunk: '#63452f', canopy: ['#f0b9cb', '#d98aa8', '#a85d7c'], size: 0.9, logs: 1 }, */
export const Species = { Birch: 0, Pine: 1, Oak: 2, Maple: 3, Willow: 4, Cedar: 5, Cherry: 6 } as const;

export interface Region {
  key: string;
  name: string;
  /** Measured centroid of the landmass on the chart, normalised 0..1. */
  at: [number, number];
  /** Shifts moisture on this region; negative is drier, which means steppe. */
  moistBias: number;
  /** Chance a dry tile becomes steppe rather than grass. */
  steppe: number;
  tundra: boolean;
  snow: boolean;
  rock: RockType;
  /** Weighted vein table. */
  ores: { ore: Ore; weight: number }[];
  /** Species that grow here and nowhere else. */
  trees: number[];
}

